styleText:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg:         #F7F7F4;
      --white:      #FFFFFF;
      --accent:     #CDB18B;
      --accent-dim: #F2E4CF;
      --dark:       #0D1117;
      --dark-2:     #1A1F2E;
      --dark-3:     #0F1520;
      --text:       #111111;
      --muted:      #6B7280;
      --muted-2:    #9CA3AF;
      --border:     rgba(0,0,0,0.07);
      --border-2:   rgba(0,0,0,0.12);
      --shadow-xs:  0 1px 3px rgba(0,0,0,0.05);
      --shadow-sm:  0 2px 10px rgba(0,0,0,0.06);
      --shadow-md:  0 8px 32px rgba(0,0,0,0.08);
      --shadow-lg:  0 20px 60px rgba(0,0,0,0.10);
      --shadow-xl:  0 40px 100px rgba(0,0,0,0.12);
      --radius-sm:  10px;
      --radius-md:  16px;
      --radius-lg:  24px;
      --radius-xl:  32px;
      --radius-full:9999px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
    a { text-decoration: none; color: inherit; }

    @keyframes fadeInUp { from { opacity:0; transform:translateY(24px);} to { opacity:1; transform:translateY(0);} }
    @keyframes pulse-dot { 0%,100%{opacity:1;transform:scale(1);} 50%{opacity:.5;transform:scale(.85);} }
    .fade-in-up { animation: fadeInUp 0.7s cubic-bezier(.22,1,.36,1) both; }
    .d1{animation-delay:.1s;} .d2{animation-delay:.2s;} .d3{animation-delay:.3s;} .d4{animation-delay:.4s;}

    .container { width:100%; max-width:1200px; margin:0 auto; padding:0 32px; }
    .eyebrow { display:inline-flex;align-items:center;gap:7px;font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:18px; }
    .eyebrow-dot { width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pulse-dot 2s ease infinite; }

    /* Buttons */
    .btn { display:inline-flex;align-items:center;gap:8px;border-radius:var(--radius-full);font-family:'Inter',sans-serif;font-weight:600;font-size:14px;cursor:pointer;transition:all .2s cubic-bezier(.22,1,.36,1);border:none;white-space:nowrap; }
    .btn-primary { background:var(--dark);color:#fff;padding:13px 28px;box-shadow:0 2px 8px rgba(0,0,0,.15); }
    .btn-primary:hover { background:var(--dark-2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.2); }
    .btn-accent  { background:var(--accent);color:var(--dark);padding:13px 28px;box-shadow:0 2px 8px rgba(205,177,139,.3); }
    .btn-accent:hover { background:#dac09e;transform:translateY(-2px);box-shadow:0 8px 24px rgba(205,177,139,.4); }
    .btn-outline { background:transparent;color:var(--text);padding:12px 24px;border:1.5px solid var(--border-2); }
    .btn-outline:hover { background:var(--white);color:#0D1117 !important;transform:translateY(-1px);box-shadow:var(--shadow-sm); }
    .btn-outline-light { background:transparent;color:rgba(255,255,255,.75);padding:12px 24px;border:1.5px solid rgba(255,255,255,.2); }
    .btn-outline-light:hover { background:rgba(255,255,255,.08); }

    /* ── Navbar ── */
    .navbar { position:fixed;top:0;left:0;right:0;z-index:1000;padding:0 40px;height:64px;display:flex;align-items:center;justify-content:space-between;background:rgba(247,247,244,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--border); }
    .nav-logo { display:flex;align-items:center;gap:9px;font-weight:800;font-size:18px;letter-spacing:-.03em; }
    .nav-logo-icon { width:30px;height:30px;background:var(--dark);border-radius:8px;display:flex;align-items:center;justify-content:center; }
    .nav-logo-icon svg { width:16px;height:16px; }
    .nav-links { display:flex;align-items:center;gap:2px;list-style:none; }
    .nav-links a { font-size:13px;font-weight:500;color:var(--muted);padding:7px 11px;border-radius:var(--radius-full);transition:all .15s;display:flex;align-items:center;gap:3px; }
    .nav-links a:hover,.nav-links a.active { color:var(--text);background:rgba(0,0,0,.04); }
    .nav-links a.active { color:var(--text);font-weight:600;background:rgba(0,0,0,.06); }
    .nav-actions { display:flex;align-items:center;gap:10px; }
    .nav-chevron { font-size:9px;opacity:.45; }
    .nav-item { position:relative;list-style:none; }
    .nav-item.has-mega:hover .nav-chevron,
    .nav-item.has-mega.mega-open .nav-chevron { transform:rotate(180deg);opacity:.7; }
    .mega-panel { position:fixed;top:64px;left:50%;transform:translateX(-50%) translateY(-6px);background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-lg);box-shadow:0 8px 16px rgba(0,0,0,.06),0 24px 64px rgba(0,0,0,.10);padding:24px;opacity:0;pointer-events:none;transition:opacity .18s ease,transform .18s ease;z-index:999; }
    .nav-item.has-mega:hover .mega-panel,
    .nav-item.has-mega.mega-open .mega-panel { opacity:1;pointer-events:auto;transform:translateX(-50%) translateY(0); }
    .mega-products  { width:1040px; }
    .mega-panel::before { content:'';position:absolute;top:0;left:24px;right:24px;height:2px;background:var(--accent);border-radius:0 0 2px 2px;opacity:.6; }
    .mega-panel::after { content:'';position:absolute;top:-18px;left:0;right:0;height:18px; }
    .mega-cols { display:flex;align-items:flex-start;gap:0; }
    .mega-col { flex:1;padding:0 28px;border-right:1px solid var(--border-2);min-width:0; }
    .mega-col:first-child { padding-left:0; }
    .mega-col:last-child  { border-right:none; }
    .mega-col-label { font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid var(--border-2);white-space:nowrap; }
    .mega-col-link { display:block;font-size:14px;color:var(--text);text-decoration:none;padding:7px 0;font-weight:500;transition:color .15s;white-space:nowrap; }
    .mega-col-link:hover { color:var(--accent); }
    .mega-col-badge { font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--accent);background:rgba(205,177,139,.15);border-radius:3px;padding:2px 5px;margin-left:6px;vertical-align:middle; }
    .mega-col-featured { flex:0 0 200px !important;padding:0 0 0 28px !important;border-right:none !important; }
    .mega-featured-img { width:100%;height:110px;border-radius:var(--radius-sm);overflow:hidden;margin-bottom:12px; }
    .mega-featured-img img { width:100%;height:100%;object-fit:cover; }
    .mega-featured-desc { font-size:12.5px;color:var(--muted);line-height:1.65;margin-bottom:12px; }
    .mega-featured-link { font-size:12.5px;font-weight:600;color:var(--text);text-decoration:none;display:flex;align-items:center;gap:4px; }
    .mega-featured-link:hover { color:var(--accent); }

    /* ── Footer ── */
    .footer { background:var(--dark);color:rgba(255,255,255,.5);padding:0 0 48px;position:relative;overflow:hidden; }
    .footer-bg { position:absolute;inset:0;z-index:0;pointer-events:none; }
    .footer-bg img { width:100%;height:100%;object-fit:cover;opacity:.35; }
    .footer .container { position:relative;z-index:1; }
    .footer-grid { display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:48px;padding-bottom:64px;border-bottom:1px solid rgba(255,255,255,.07); }
    .footer-brand p { font-size:13px;color:rgba(255,255,255,.38);line-height:1.7;margin-top:14px;max-width:220px; }
    .footer-col-title { font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:16px; }
    .footer-col ul { list-style:none; }
    .footer-col ul li { margin-bottom:10px; }
    .footer-col ul li a { font-size:13px;color:rgba(255,255,255,.48);transition:color .15s; }
    .footer-col ul li a:hover { color:#fff; }
    .footer-bottom { display:flex;align-items:center;justify-content:space-between;padding-top:32px; }
    .footer-bottom-text { font-size:12px;color:rgba(255,255,255,.25); }
    .footer-socials { display:flex;gap:8px; }
    .footer-social { width:32px;height:32px;border-radius:8px;border:1px solid rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;font-size:12px;cursor:pointer;transition:all .15s; }
    .footer-social:hover { border-color:rgba(255,255,255,.3);color:#fff; }

    /* ── Article Hero ── */
    .post-hero {
      padding: 120px 0 0;
      background: var(--bg);
      position: relative;
      overflow: hidden;
    }
    .post-breadcrumb {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: var(--muted);
      margin-bottom: 24px;
    }
    .post-breadcrumb a { color: var(--muted); transition: color .15s; }
    .post-breadcrumb a:hover { color: var(--text); }
    .post-breadcrumb-sep { opacity: .4; font-size: 10px; }
    .post-cat-pill {
      display: inline-flex;
      align-items: center;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--accent);
      background: rgba(205,177,139,.12);
      border: 1px solid rgba(205,177,139,.3);
      border-radius: var(--radius-full);
      padding: 5px 14px;
      margin-bottom: 20px;
    }
    .post-hero h1 {
      font-size: clamp(32px, 4.5vw, 56px);
      font-weight: 900;
      letter-spacing: -.04em;
      line-height: 1.08;
      color: var(--dark);
      max-width: 820px;
      margin-bottom: 28px;
    }
    .post-hero h1 em { font-style: italic; font-family: 'DM Serif Display', serif; font-weight: 400; } h2 em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; } .section-headline em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; }
    .post-meta {
      display: flex;
      align-items: center;
      gap: 24px;
      flex-wrap: wrap;
      padding-bottom: 40px;
    }
    .post-meta-author {
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .post-avatar {
      width: 36px; height: 36px;
      border-radius: 50%;
      background: var(--accent);
      color: #fff;
      font-size: 13px;
      font-weight: 700;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .post-author-name { font-size: 13px; font-weight: 700; color: var(--text); }
    .post-author-role { font-size: 11px; color: var(--muted); }
    .post-meta-divider { width: 1px; height: 28px; background: var(--border-2); }
    .post-meta-item {
      font-size: 12.5px;
      color: var(--muted);
      display: flex;
      align-items: center;
      gap: 5px;
    }
    .post-meta-item strong { color: var(--text); font-weight: 600; }

    /* ── Article Banner Image ── */
    .post-banner {
      width: 100%;
      height: 420px;
      background: linear-gradient(135deg, #e8d5b7 0%, #f5ebe0 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 96px;
      position: relative;
      overflow: hidden;
    }
    .post-banner::after {
      content: '';
      position: absolute;
      bottom: 0; left: 0; right: 0;
      height: 80px;
      background: linear-gradient(to bottom, transparent, var(--bg));
    }

    /* ── Article Body ── */
    .post-layout {
      display: grid;
      grid-template-columns: 1fr 280px;
      gap: 64px;
      align-items: flex-start;
      padding: 64px 0 100px;
    }
    .post-content { min-width: 0; }
    .post-lead {
      font-size: 18px;
      font-weight: 600;
      color: var(--dark);
      line-height: 1.7;
      margin-bottom: 36px;
      padding-bottom: 36px;
      border-bottom: 1px solid var(--border);
    }
    .post-body { font-size: 16px; color: #333; line-height: 1.85; }
    .post-body h2 {
      font-size: 24px;
      font-weight: 800;
      letter-spacing: -.03em;
      color: var(--dark);
      margin: 48px 0 18px;
      line-height: 1.25;
    }
    .post-body h3 {
      font-size: 18px;
      font-weight: 700;
      color: var(--dark);
      margin: 36px 0 14px;
    }
    .post-body p { margin-bottom: 22px; }
    .post-body ul, .post-body ol {
      margin: 0 0 22px 24px;
    }
    .post-body li { margin-bottom: 10px; }
    .post-body strong { color: var(--dark); font-weight: 700; }

    /* Pull quote */
    .post-quote {
      border-left: 3px solid var(--accent);
      padding: 20px 28px;
      margin: 40px 0;
      background: var(--white);
      border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    }
    .post-quote p {
      font-size: 19px;
      font-family: 'DM Serif Display', serif;
      font-weight: 400;
      font-style: italic;
      color: var(--dark);
      line-height: 1.55;
      margin: 0;
    }
    .post-quote cite {
      display: block;
      margin-top: 12px;
      font-size: 12px;
      font-style: normal;
      font-family: 'Inter', sans-serif;
      color: var(--muted);
      font-weight: 600;
      letter-spacing: .05em;
    }

    /* Inline callout box */
    .post-callout {
      background: var(--accent-dim);
      border: 1px solid rgba(205,177,139,.3);
      border-radius: var(--radius-md);
      padding: 22px 26px;
      margin: 36px 0;
    }
    .post-callout-label {
      font-size: 10px;
      font-weight: 700;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 8px;
    }
    .post-callout p {
      font-size: 14px;
      color: var(--text);
      margin: 0;
      line-height: 1.7;
    }

    /* Stat row */
    .post-stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin: 40px 0;
    }
    .post-stat {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 20px;
      text-align: center;
    }
    .post-stat-num {
      font-size: 32px;
      font-weight: 900;
      letter-spacing: -.04em;
      color: var(--dark);
      line-height: 1;
      margin-bottom: 6px;
    }
    .post-stat-num em { color: var(--accent); font-style: normal; }
    .post-stat-label { font-size: 12px; color: var(--muted); font-weight: 500; }

    /* ── Sidebar ── */
    .post-sidebar { position: sticky; top: 88px; }
    .sidebar-card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 24px;
      margin-bottom: 20px;
    }
    .sidebar-card-title {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--muted);
      margin-bottom: 16px;
      padding-bottom: 12px;
      border-bottom: 1px solid var(--border);
    }
    .toc-link {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      padding: 7px 0;
      font-size: 13px;
      color: var(--muted);
      font-weight: 500;
      border-radius: 6px;
      transition: color .15s;
      cursor: pointer;
    }
    .toc-link:hover { color: var(--text); }
    .toc-link.active { color: var(--accent); font-weight: 600; }
    .toc-num {
      font-size: 10px;
      font-weight: 700;
      color: var(--muted-2);
      min-width: 16px;
      padding-top: 2px;
    }
    .sidebar-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      color: var(--text);
      background: var(--bg);
      border: 1px solid var(--border-2);
      border-radius: var(--radius-full);
      padding: 5px 12px;
      margin: 0 4px 8px 0;
      transition: all .15s;
      cursor: pointer;
    }
    .sidebar-tag:hover { background: var(--dark); color: #fff; border-color: var(--dark); }
    .share-btn {
      display: flex;
      align-items: center;
      gap: 8px;
      width: 100%;
      padding: 10px 14px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--border-2);
      background: var(--white);
      font-size: 13px;
      font-weight: 600;
      color: var(--text);
      cursor: pointer;
      transition: all .15s;
      margin-bottom: 8px;
      font-family: 'Inter', sans-serif;
    }
    .share-btn:hover { background: var(--bg); border-color: var(--accent); }
    .share-btn:last-child { margin-bottom: 0; }

    /* ── Author Bio ── */
    .post-author-card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 32px;
      margin-top: 56px;
      display: flex;
      gap: 24px;
      align-items: flex-start;
    }
    .post-author-avatar-lg {
      width: 64px; height: 64px;
      border-radius: 50%;
      background: var(--accent);
      color: #fff;
      font-size: 22px;
      font-weight: 700;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .post-author-card h4 { font-size: 16px; font-weight: 800; color: var(--dark); margin-bottom: 2px; }
    .post-author-card .role { font-size: 12px; color: var(--accent); font-weight: 600; margin-bottom: 12px; }
    .post-author-card p { font-size: 13.5px; color: var(--muted); line-height: 1.7; }

    /* ── Related Articles ── */
    .related-section { background: var(--white); padding: 80px 0 100px; }
    .related-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 40px;
    }
    .related-header h2 { font-size: 28px; font-weight: 900; letter-spacing: -.03em; }
    .related-header a { font-size: 13px; font-weight: 600; color: var(--accent); }
    .related-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
    .blog-card {
      background: var(--white);border-radius:var(--radius-lg);overflow:hidden;
      border:1px solid var(--border);transition:all .25s cubic-bezier(.22,1,.36,1);
      display:flex;flex-direction:column;
    }
    .blog-card:hover { transform:translateY(-5px);box-shadow:var(--shadow-lg);border-color:transparent; }
    .blog-card-img { height:180px;position:relative;overflow:hidden; }
    .grad-tan    { background:linear-gradient(135deg,#e8d5b7 0%,#f5ebe0 100%); }
    .grad-blue   { background:linear-gradient(135deg,#c9d8f0 0%,#e8f0fd 100%); }
    .grad-green  { background:linear-gradient(135deg,#c2ddc5 0%,#e5f2e7 100%); }
    .grad-purple { background:linear-gradient(135deg,#d4c8f0 0%,#ede8fb 100%); }
    .grad-coral  { background:linear-gradient(135deg,#f0c8c2 0%,#fbe8e5 100%); }
    .grad-slate  { background:linear-gradient(135deg,#c8d4dc 0%,#e5ecf0 100%); }
    .blog-card-img-inner { width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:42px; }
    .blog-card-cat {
      position:absolute;top:14px;left:14px;
      font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
      background:rgba(255,255,255,.92);color:var(--text);
      padding:4px 12px;border-radius:var(--radius-full);
      box-shadow:0 1px 4px rgba(0,0,0,.08);
    }
    .blog-card-body { padding:20px 22px 22px;flex:1;display:flex;flex-direction:column; }
    .blog-card-title { font-size:15px;font-weight:800;letter-spacing:-.02em;color:var(--text);line-height:1.35;margin-bottom:8px;transition:color .15s; }
    .blog-card:hover .blog-card-title { color:var(--dark); }
    .blog-card-excerpt { font-size:12.5px;color:var(--muted);line-height:1.7;flex:1;margin-bottom:18px; }
    .blog-card-footer { display:flex;align-items:center;justify-content:space-between;padding-top:14px;border-top:1px solid var(--border); }
    .blog-card-author { display:flex;align-items:center;gap:8px; }
    .blog-card-avatar { width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#fff;flex-shrink:0; }
    .blog-card-author-name { font-size:11.5px;font-weight:600;color:var(--text); }
    .blog-card-read-time { font-size:11px;color:var(--muted-2);font-weight:500; }

    /* ── FAQ section (matching other pages) ── */
    .faq-header-row { display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:48px;gap:32px; }
    .faq-header-left h2 { font-size:clamp(28px,3.5vw,44px);font-weight:900;letter-spacing:-.04em;line-height:1.1;margin-bottom:12px; }
    .faq-header-left p { font-size:15px;color:var(--muted);max-width:420px;line-height:1.7; }
    .faq-view-all { font-size:12.5px;font-weight:700;color:var(--text);border:1.5px solid var(--border-2);padding:9px 20px;border-radius:var(--radius-full);white-space:nowrap;transition:all .15s;flex-shrink:0;margin-top:6px; }
    .faq-view-all:hover { background:var(--dark);color:#fff;border-color:var(--dark); }
    .faq-cols { display:grid;grid-template-columns:1fr 1fr;gap:0 40px; }
    .faq-item { border-bottom:1px solid var(--border);overflow:hidden; }
    .faq-q { display:flex;justify-content:space-between;align-items:center;padding:20px 0;font-size:15px;font-weight:700;cursor:pointer;user-select:none;gap:16px;color:var(--text); }
